import { useCmsDatabase } from "@/wab/client/components/cms/cms-contexts";
import {
  DefaultCmsContentPageProps,
  PlasmicCmsContentPage,
} from "@/wab/client/plasmic/plasmic_kit_cms/PlasmicCmsContentPage";
import { Redirect } from "@/wab/client/route/Redirect";
import { Switch, switchCase, switchDefault } from "@/wab/client/route/Switch";
import { useMatchedRoute } from "@/wab/client/route/useMatchedRoute";
import { APP_ROUTES } from "@/wab/shared/route/app-routes";
import { HTMLElementRefOf } from "@plasmicapp/react-web";
import * as React from "react";

export type CmsContentPageProps = DefaultCmsContentPageProps;

function CmsContentPage_(
  props: CmsContentPageProps,
  ref: HTMLElementRefOf<"div">
) {
  const m = useMatchedRoute(APP_ROUTES.cmsContentRoot);
  const database = useCmsDatabase(m?.pathParams.databaseId);
  if (!m || !database) {
    return null;
  }

  // Sort to make archived tables last on the list
  // Sorting by id to make it stable.
  const tables = database.tables.sort((a, b) =>
    a.isArchived == b.isArchived
      ? b.id.localeCompare(a.id)
      : a.isArchived
      ? 1
      : -1
  );
  return (
    <Switch
      cases={[
        switchCase({
          route: APP_ROUTES.cmsModelContent,
          render: ({ databaseId, tableId }) => {
            if (!tables.find((t) => t.id === tableId)) {
              return (
                <Redirect to={APP_ROUTES.cmsContentRoot.fill({ databaseId })} />
              );
            } else {
              return <PlasmicCmsContentPage root={{ ref }} {...props} />;
            }
          },
        }),
        switchCase({
          route: APP_ROUTES.cmsContentRoot,
          render: () => {
            if (tables.length > 0) {
              return (
                <Redirect
                  to={APP_ROUTES.cmsModelContent.fill({
                    databaseId: database.id,
                    tableId: tables[0].id,
                  })}
                />
              );
            } else {
              return (
                <PlasmicCmsContentPage
                  noModels={true}
                  root={{ ref }}
                  {...props}
                />
              );
            }
          },
        }),
        switchDefault({ render: () => null }),
      ]}
    />
  );
}

const CmsContentPage = React.forwardRef(CmsContentPage_);
export default CmsContentPage;
